#include "gpu_batched_backward.cuh"
#include <cstdio>
int main(){using namespace tao::dual;try{for(int rows:{129,512}){int cols=131,S=4;Vec w(rows*cols),x(cols*S),g(rows*S);for(size_t i=0;i<w.size();++i)w[i]=float(int(i%13)-6)*.03f;for(size_t i=0;i<x.size();++i)x[i]=float(int(i%7)-3)*.07f;for(size_t i=0;i<g.size();++i)g[i]=float(int(i%11)-5)*.02f;Device W(w),X(x),G(g),dx(Vec(cols*S,.1f)),dr(Vec(cols*S,.1f)),dw(Vec(rows*cols,.2f)),wr(Vec(rows*cols,.2f));for(int s=0;s<S;++s){ds_dx_tiled<<<(cols+31)/32,dim3(32,8)>>>(W.p,G.p+s*rows,dr.p+s*cols,rows,cols);ds_linear_dw<<<(rows*cols+127)/128,128>>>(X.p+s*cols,G.p+s*rows,wr.p,rows,cols);}ds_batch_dx<<<dim3((cols+31)/32,S),dim3(32,8)>>>(W.p,G.p,dx.p,rows,cols);ds_batch_dw<<<(rows*cols+127)/128,128>>>(X.p,G.p,dw.p,rows,cols,S);check(cudaGetLastError());if(dx.host()!=dr.host()||dw.host()!=wr.host())return 1;}printf("PASS batch4 backward dx and shared dw match serial accumulations with nonzero initial grads\n");return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 2;}}
